/* Wakemu administration. All content is supplied by the authenticated API. */
'use strict';
const $ = (selector) => document.querySelector(selector);
const escapeHTML = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = value => new Intl.NumberFormat('en-US').format(Number(value || 0));
const date = value => value ? new Date(value).toLocaleString('en-US') : '—';
const status = (enabled, yes='Active', no='Inactive') => `<span class="badge ${enabled ? 'good' : ''}">${enabled ? yes : no}</span>`;
const pages = {
 dashboard:['Server overview','Current world activity and service health.'],
 accounts:['Accounts','Manage access, characters, and account balances.'],
 maps:['Maps','Explore named destinations, terrain, population, and teleport locations.'],
 characters:['Characters','Find character locations, deliver items, and teleport players.'],
 settings:['Settings','Edit server configuration and apply service changes.'],
 profiler:['Profiler','Inspect available world performance measurements.'],
 articles:['Shop articles','Manage products, categories, and kama prices.'],
 categories:['Shop categories','Organize the in-game shop catalogue.'],
 objectives:['Objectives & missions','Tasks, achievements, recurring challenges, Almanax, and PvP missions.'],
 audit:['Change history','Review who changed accounts, maps, and shop settings.']
};
let session=null, page='dashboard', offset=0, search='', renderVersion=0, saveEditor=null, refreshTimer;
async function api(path, options={}) {
 const controller=new AbortController(), timer=setTimeout(()=>controller.abort(),20000);
 try {
  const headers={'Accept':'application/json',...(options.body ? {'Content-Type':'application/json'} : {})};
  if (options.method && options.method !== 'GET' && session?.csrf_token) headers['X-CSRF-Token']=session.csrf_token;
  const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers,signal:controller.signal});
  const result=await response.json().catch(()=>({}));
  if (!response.ok) { if(response.status===401 && path!='/login') showLogin(); throw new Error(result.error || result.message || `Could not complete the operation (${response.status}).`); }
  return result;
 } catch(error) { if(error.name==='AbortError') throw new Error('The server took too long to respond. Try again.'); throw error; }
 finally {clearTimeout(timer);}
}
function showLogin(){session=null;clearInterval(refreshTimer);$('#shell').hidden=true;$('#login').hidden=false;}
function showShell(){ $('#login').hidden=true;$('#shell').hidden=false;$('#identity').textContent=session.username; navigate();clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(page==='dashboard'&&!document.hidden&&!$('#editor').open)load();},15000); }
function notice(text,failed=false){const el=$('#notice');el.textContent=text;el.hidden=!text;el.classList.toggle('failed',failed);}
function table(columns, rows, empty='No records to display.') {
 if(!rows.length)return `<div class="empty"><strong>No results</strong>${escapeHTML(empty)}</div>`;
 return `<div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th scope="col">${escapeHTML(c[0])}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td>${c[1](row)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
const text = key => row => escapeHTML(row[key]);
function editButton(row,label='Edit'){return `<button class="quiet" data-edit="${escapeHTML(row.id)}">${label}</button>`;}
function pager(data){return `<div class="pagination"><span>${number(data.total)} records${data.total ? ` · ${offset+1}–${Math.min(offset+(data.items?.length||0),data.total)}` : ''}</span><div class="inline-actions"><button class="quiet" data-offset="${Math.max(0,offset-30)}" ${offset===0?'disabled':''}>Previous</button><button class="quiet" data-offset="${offset+30}" ${offset+30>=data.total?'disabled':''}>Next</button></div></div>`;}
function searchbar(placeholder){return `<form id="search-form" class="searchbar"><label>Search<input name="search" value="${escapeHTML(search)}" placeholder="${escapeHTML(placeholder)}" type="search"></label><button type="submit">Search</button></form>`;}
function navigate(){ const next=location.hash.slice(1).split('?')[0]||'dashboard';page=pages[next]?next:'dashboard';offset=0;search='';notice('');$('#page-title').textContent=pages[page][0];$('#page-description').textContent=pages[page][1];document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});load();}
async function load(){
 if(!session)return;const version=++renderVersion;$('#view').innerHTML='<div class="loading">Loading information…</div>';
 $('#page-actions').innerHTML=['accounts','articles','categories'].includes(page)?`<button class="primary" id="create">${{accounts:'Create account',articles:'Add article',categories:'Create category'}[page]}</button>`:'';
 if($('#create'))$('#create').onclick=()=>openRecord(null);
 try{
  if(page==='objectives'){if(objectiveTab==='policies'){await renderRewardPolicies(version);return;}if(objectiveTab==='ranking'){await renderObjectiveRanking(version);return;}if(objectiveTab==='profiles'){await renderChallengeProfiles(version);return;}await renderObjectives(version);return;}
  if(page==='settings'){await renderSettings(version);return;}
  if(page==='profiler'){const data=await api('/profiler');if(version!==renderVersion)return;renderProfiler(data);return;}
  if(page==='dashboard'){const data=await api('/dashboard');if(version!==renderVersion)return;renderDashboard(data);return;}
  const path={accounts:'/accounts',characters:'/characters',maps:'/maps',articles:'/shop/articles',categories:'/shop/categories',audit:'/audit'}[page];
  const data=await api(`${path}?limit=30&offset=${offset}&search=${encodeURIComponent(search)}`);if(version!==renderVersion)return;
  const columns={
   accounts:[['Account',r=>`<strong>${escapeHTML(r.username)}</strong><br><small class="muted">#${escapeHTML(r.id)}</small>`],['Access',r=>r.banned?'<span class="badge">Banned</span>':status(r.online,'Online','Offline')],['Role',r=>r.is_admin?'Administrator':'Player'],['Characters',r=>number(r.character_count)],['Kamas',r=>number(r.kamas)],['',r=>editButton(r,'View account')]],
   characters:characterColumns(),
   maps:[['Map',r=>`<strong>${escapeHTML(r.name||'Unnamed')}</strong><br><small class="muted">#${escapeHTML(r.id)}</small>`],['Characters',r=>number(r.character_count)],['Online',r=>number(r.online_count)],['Terrain',r=>r.installed_geometry?'Installed':'Unavailable'],['Content',r=>`${number(r.monster_groups_count)} groups · ${number(r.resources_count)} resources`],['',r=>editButton(r,'View map')]],
   articles:[['Article',r=>`<strong>${escapeHTML(r.name)}</strong><br><small class="muted">Item #${escapeHTML(r.item_ref)}</small>`],['Category',text('category')],['Price',r=>`${number(r.price_kamas)} kamas`],['Units',r=>number(r.quantity)],['Status',r=>status(r.enabled)],['',editButton]],
   categories:[['Category',r=>`<strong>${escapeHTML(r.name)}</strong><br><small class="muted">${escapeHTML(r.key)}</small>`],['Description',text('description')],['Order',text('sort_order')],['Status',r=>status(r.enabled)],['',editButton]],
   audit:[['Date',r=>escapeHTML(date(r.created_at))],['Operator',text('operator')],['Action',text('action')],['Record',text('target')],['Changes',r=>`<details><summary>View details</summary><pre class="audit-data">${escapeHTML(JSON.stringify({before:r.before_data,after:r.after_data},null,2))}</pre></details>`]],

  }[page];
  $('#view').innerHTML=(page==='maps'?'<p class="muted">Ordered by player activity. Open a map to inspect terrain and choose a teleport destination.</p>':'')+(page==='audit'?'':searchbar({accounts:'Username',characters:'Character or account name',maps:'Map name or ID',articles:'Name or identifier',categories:'Name or key'}[page]))+`<section class="panel">${table(columns,data.items||[],page==='audit'?'Saved changes will appear here.':'Try another search or create a record.')}${pager(data)}</section>`+(page==='articles'?'<p class="muted">Units are the quantity delivered per purchase. Stock is unlimited. Prices use the same kama balance as the game.</p>':'');
  if($('#search-form'))$('#search-form').onsubmit=e=>{e.preventDefault();search=new FormData(e.target).get('search').trim();offset=0;load();};
  document.querySelectorAll('[data-offset]').forEach(b=>b.onclick=()=>{offset=Number(b.dataset.offset);load();});
  bindCharacterButtons();
  document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRecord(data.items.find(r=>String(r.id)===b.dataset.edit)));
 }catch(error){if(version===renderVersion){$('#view').innerHTML='<section class="panel"><div class="empty"><strong>Could not load information</strong>Use Refresh to try again.</div></section>';notice(error.message,true);}}
}
function renderDashboard(data){const health=data.services?.world;$('#server-health').textContent=health ? (health.ok?'World available':'World unavailable') : 'World status pending';const counts=data.counts||{};const metrics=[['Players online',counts.online],['Registered accounts',counts.accounts],['Characters',counts.characters],['Active fights',counts.active_fights]];$('#view').innerHTML=`<section class="metrics" aria-label="Server summary">${metrics.map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${number(value)}</strong></div>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>Online players</h2><span class="badge">${escapeHTML(new Date().toLocaleTimeString('en-US'))} · every 15 s</span></div>${table([['Character',r=>`<strong>${escapeHTML(r.name)}</strong>`],['Account',text('username')],['Level',r=>number(r.level)],['Location',locationCell],['',r=>`<button type="button" class="quiet" data-character="${escapeHTML(r.id??r.character_id)}">Manage character</button>`]],data.online||[],'Players will appear here when they enter the world.')}</section><section class="panel"><div class="panel-heading"><h2>Service health</h2></div>${table([['Service',text('label')],['Status',r=>status(r.ok,'Available','Unavailable')]],Object.entries(data.services||{}).map(([key,v])=>({...v,label:{world:'World server',shop:'Shop'}[key]||key})))}</section><p class="muted">Shows active character sessions. After a server interruption, a session may remain visible for up to 5 minutes. The table shows up to 100 players.</p>`;bindCharacterButtons();}
function field(name,label,value='',options={}){const id='field-'+name;const cls=options.wide?' class="field-wide"':'';if(options.type==='checkbox')return `<label${cls}><input id="${id}" name="${name}" type="checkbox" ${value?'checked':''}>${escapeHTML(label)}</label>`;let control;if(options.choices)control=`<select id="${id}" name="${name}">${options.choices.map(c=>`<option value="${escapeHTML(c[0])}" ${String(c[0])===String(value)?'selected':''}>${escapeHTML(c[1])}</option>`).join('')}</select>`;else if(options.type==='textarea')control=`<textarea id="${id}" name="${name}">${escapeHTML(value)}</textarea>`;else control=`<input id="${id}" name="${name}" type="${options.type||'text'}" value="${escapeHTML(value)}" ${options.required?'required':''} ${options.min!==undefined?`min="${options.min}"`:''} ${options.max!==undefined?`max="${options.max}"`:''} ${options.type==='password'?'autocomplete="new-password"':''}>`;return `<label${cls}>${escapeHTML(label)}${control}${options.note?`<span class="field-note">${escapeHTML(options.note)}</span>`:''}</label>`;}
async function openRecord(row){if(page==='characters')return openCharacter(row.id);const kind=page;const recordID=row?.id;notice('');$('#editor-form button[type=submit]').hidden=false;$('#cancel-editor').textContent='Cancel';try{
 let detail=row||{},extra='';
 if(row&&['accounts','maps'].includes(kind))detail=await api(`/${kind}/${recordID}`);
 let fields='',title='';
 if(kind==='accounts'){
 title=row?`Account: ${detail.username}`:'Create account';fields=field('username','Username',detail.username||'',{required:true})+field('password',row?'New password (optional)':'Password','',{type:'password',required:!row})+field('kamas','Kama balance',detail.kamas||0,{type:'number',min:0,max:2147483647,required:true})+field('is_admin','Administrator permissions',detail.is_admin,{type:'checkbox'});
 if(row){extra=`<section class="action-section"><h2>Account access</h2><p>${detail.banned?'Banned'+(detail.ban?.expires_at?' until '+escapeHTML(new Date(detail.ban.expires_at).toLocaleString("en-US")):' permanently'):'Access allowed'}${detail.ban?' · '+escapeHTML(detail.ban.reason):''}</p><label>Reason<textarea id="ban-reason" maxlength="1000"></textarea></label><label>Ban until (local time; leave empty for permanent)<input id="ban-expiry" type="datetime-local"></label><div class="inline-actions"><button type="button" id="ban-account">Ban account</button>${detail.banned?'<button type="button" id="unban-account">Unban account</button>':''}</div><p class="muted">Banning revokes all tokens and disconnects active sessions. Unbanning requires a new login.</p></section><h2>Account characters</h2>${table([['Name',text('name')],['Level',text('level')],['Location',locationCell],['',r=>`<button type="button" class="quiet" data-character="${escapeHTML(r.id)}">Manage character</button>`]],detail.characters||[],'This account has no characters.')}<p class="muted">The player must be offline before editing an account.</p>`;}
 }else if(kind==='maps'){
 title=detail.name||`Map #${recordID}`;fields=field('name','Administrative name',detail.name_source==='operator'?detail.name:'',{wide:true,note:'Optional display name override.'})+field('notes','Notes',detail.notes||'',{type:'textarea',wide:true});extra=renderMapDetail(detail);
 }else if(kind==='categories'){
 title=row?'Edit category':'Create category';fields=field('key','Key',detail.key||'',{required:true,note:'Unique identifier, for example: weapons.'})+field('name','Display name',detail.name||'',{required:true})+field('description','Description',detail.description||'',{type:'textarea',wide:true})+field('sort_order','Order',detail.sort_order||0,{type:'number',required:true})+field('enabled','Visible in the shop',detail.enabled??true,{type:'checkbox'});
 }else if(kind==='articles'){
 const categories=await allCategories();title=row?'Edit article':'Add article';fields=field('key','Key',detail.key||'',{required:true})+field('name','Display name',detail.name||'',{required:true})+`<div class="field-wide"><label>Search game items<input id="item-search" type="search" placeholder="Name or reference, for example 2027"></label><div id="item-results" hidden class="results"></div></div>`+field('item_ref','Item reference',detail.item_ref||'',{type:'number',required:true,min:1,max:2147483647})+field('category','Category',detail.category||'items',{choices:(categories.items||[]).map(c=>[c.key,c.name+(c.enabled?'':' (inactive)')])})+field('quantity','Units per purchase',detail.quantity||1,{type:'number',required:true,min:1,max:32767})+field('price_kamas','Price in kamas',detail.price_kamas||1000,{type:'number',required:true,min:1,max:2147483647})+field('description','Description',detail.description||'',{type:'textarea',wide:true})+field('enabled','Available for purchase',detail.enabled??true,{type:'checkbox',wide:true});
 }
 $('#editor-title').textContent=title;$('#editor-fields').innerHTML=`<div class="field-grid">${fields}</div>${extra}`;$('#editor-error').textContent='';$('#editor-form button[type=submit]').disabled=false;
 saveEditor=async form=>{const body=Object.fromEntries(new FormData(form));for(const name of ['kamas','sort_order','item_ref','quantity','price_kamas'])if(name in body)body[name]=Number(body[name]);for(const name of ['is_admin','enabled'])if(form.elements[name])body[name]=form.elements[name].checked;if(row&&body.password==='')delete body.password;const path={accounts:'/accounts',characters:'/characters',maps:'/maps',articles:'/shop/articles',categories:'/shop/categories'}[kind];await api(path+(recordID!=null?'/'+encodeURIComponent(recordID):''),{method:recordID!=null?'PATCH':'POST',body:JSON.stringify(body)});$('#editor').close();await load();notice(recordID!=null?'Changes saved.':'Record created.');};
 $('#editor').showModal();
 bindCharacterButtons();
 if(kind==='accounts'&&row){for(const action of ['ban','unban']){const button=$('#'+action+'-account');if(button)button.onclick=async()=>{button.disabled=true;$('#editor-error').textContent='';try{const reason=$('#ban-reason').value.trim();if(!reason)throw new Error('Enter a reason.');const body={reason};if(action==='ban'){const expiry=$('#ban-expiry').value;body.expires_at=expiry?new Date(expiry).toISOString():null;}await api('/accounts/'+recordID+'/'+action,{method:'POST',body:JSON.stringify(body)});$('#editor').close();await load();notice(action==='ban'?'Account banned.':'Account access restored.');}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};}}
 if(kind==='maps')bindMapActions(detail);
 if(kind==='articles'){let timeout,itemVersion=0;$('#item-search').oninput=e=>{clearTimeout(timeout);const query=e.target.value.trim();const version=++itemVersion;if(!query){$('#item-results').hidden=true;return;}timeout=setTimeout(async()=>{const results=$('#item-results');results.hidden=false;results.textContent='Searching…';try{const data=await api('/items?search='+encodeURIComponent(query)+'&limit=20');if(version!==itemVersion)return;results.innerHTML=(data.items||[]).map(item=>`<button type="button" data-ref="${escapeHTML(item.reference)}" data-name="${escapeHTML(item.name)}" data-maximum="${escapeHTML(item.maximum)}">${escapeHTML(item.name)} <span class="muted">#${escapeHTML(item.reference)}</span></button>`).join('')||'<p class="muted">No items found.</p>';results.querySelectorAll('button').forEach(b=>b.onclick=()=>{formSet('item_ref',b.dataset.ref);$('#field-quantity').max=Math.min(Number(b.dataset.maximum)||32767,32767);if(!$('#field-name').value)formSet('name',b.dataset.name);results.hidden=true;$('#item-search').value=b.dataset.name;});}catch(error){results.textContent=error.message;}},300);};}
 }catch(error){notice(error.message,true);}}
async function allCategories(){const result={items:[]};let next=0;while(true){const data=await api('/shop/categories?limit=100&offset='+next);result.items.push(...(data.items||[]));next+=data.items?.length||0;if(next>=data.total||!data.items?.length)break;}return result;}
function formSet(name,value){$('#editor-form').elements[name].value=value;}
$('#editor-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button[type=submit]');button.disabled=true;$('#editor-error').textContent='';try{if(saveEditor)await saveEditor(event.target);}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();
$('#login-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{session=await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});event.target.reset();showShell();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}};
$('#logout').onclick=async()=>{try{await api('/logout',{method:'POST'});showLogin();}catch(error){notice(error.message,true);}};
$('#refresh').onclick=()=>{notice('');load();};window.addEventListener('hashchange',()=>{if(session)navigate();});
(async()=>{try{session=await api('/session');showShell();}catch{showLogin();}})();
function locationCell(r){return `<span class="location"><strong>${escapeHTML(r.map_name||'Map #'+r.map_id)}</strong><br><small class="muted">${escapeHTML(r.x??'—')}, ${escapeHTML(r.y??'—')}, ${escapeHTML(r.z??0)} · instance ${escapeHTML(r.instance_id??0)}</small></span>`;}
function characterColumns(){return [['Character',r=>`<strong>${escapeHTML(r.name)}</strong><br><small class="muted">#${escapeHTML(r.id)} · ${escapeHTML(r.username||'Account #'+r.account_id)}</small>`],['Level',r=>number(r.level)],['Session',r=>status(r.online,'Online','Offline')],['Location',locationCell],['',r=>`<button type="button" class="quiet" data-character="${escapeHTML(r.id)}">Manage character</button>`]];}
function bindCharacterButtons(){document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>openCharacter(b.dataset.character));}
function detailsGrid(entries){return `<dl class="detail-list">${entries.map(([label,value])=>`<div><dt>${escapeHTML(label)}</dt><dd>${escapeHTML(value??'—')}</dd></div>`).join('')}</dl>`;}
function setupItemSearch(inputID,resultID,onSelect){let timer,version=0;$(inputID).oninput=e=>{clearTimeout(timer);const query=e.target.value.trim(),v=++version;const result=$(resultID);if(!query){result.hidden=true;return;}timer=setTimeout(async()=>{result.hidden=false;result.textContent='Searching…';try{const data=await api('/items?search='+encodeURIComponent(query)+'&limit=20');if(v!==version)return;result.innerHTML=(data.items||[]).map(item=>`<button type="button" data-ref="${escapeHTML(item.reference)}" data-maximum="${escapeHTML(item.maximum)}" data-name="${escapeHTML(item.name)}">${escapeHTML(item.name)} <span class="muted">#${escapeHTML(item.reference)}</span></button>`).join('')||'<p>No items found.</p>';result.querySelectorAll('button').forEach(b=>b.onclick=()=>{onSelect(b.dataset);result.hidden=true;$(inputID).value=b.dataset.name;});}catch(error){result.textContent=error.message;}},250);};}
const worldOperations=new Map();
async function submitWorldAction(characterID,action,body,button){const output=$('#world-action-status'),key=String(characterID)+':'+action;let operation=worldOperations.get(key);if(operation&&JSON.stringify(operation.body)!==JSON.stringify(body)){output.hidden=false;output.textContent='A previous command is unresolved. Check its status before submitting a different command.';body=operation.body;}if(!operation){operation={body:structuredClone(body),request_id:crypto.randomUUID(),handle:null};worldOperations.set(key,operation);}button.disabled=true;output.hidden=false;output.textContent=operation.handle?'Checking command status…':'Submitting command…';let terminal=false;try{let receipt=operation.handle?await api('/actions/'+encodeURIComponent(operation.handle)):await api(`/characters/${characterID}/${action}`,{method:'POST',body:JSON.stringify({...operation.body,request_id:operation.request_id})});operation.handle=receipt.handle||receipt.id||receipt.action_id||operation.handle;for(let tries=0;tries<60;tries++){if(receipt.status==='completed'){terminal=true;worldOperations.delete(key);output.textContent='Completed by the world server. '+(receipt.result?.message||'');return;}if(['failed','cancelled'].includes(receipt.status)){terminal=true;worldOperations.delete(key);throw new Error(receipt.error||receipt.result?.error||'The world server rejected this command.');}output.textContent=`Command ${receipt.status||'pending'}. Waiting for the world server…`;if(!operation.handle)throw new Error('The server returned no command receipt.');await new Promise(resolve=>setTimeout(resolve,1000));receipt=await api('/actions/'+encodeURIComponent(operation.handle));}output.textContent='Still pending. Receipt: '+operation.handle+'. Use Check status to continue waiting; the command will not be submitted again.';}catch(error){output.textContent=error.message+(terminal?'':operation.handle?' Receipt: '+operation.handle+'. Use Check status to resume.':' Submission status is unknown. Retry will reuse the same request identifier.');}finally{button.disabled=false;button.textContent=terminal?(action==='items'?'Deliver item':'Teleport character'):operation.handle?'Check status':'Retry same command';}}

function bindAdventuresLaunch(characterID){
 const button=$('#open-adventures'),panel=$('#adventures-link-panel'),input=$('#adventures-player-link'),output=$('#adventures-link-status'),copy=$('#copy-adventures-link');
 let playerURL=null;
 button.onclick=async()=>{
  let popup=null;
  try{popup=window.open(playerURL||'about:blank','_blank');if(popup)popup.opener=null;}catch(_){/* A blocked popup leaves the reusable link available below. */}
  if(playerURL){if(!popup){output.textContent='The popup was blocked. Copy the link or select it and open it in your browser.';input.focus();input.select();}return;}
  button.disabled=true;button.textContent='Creating player link…';
  try{
   const result=await api('/objectives/player-launch',{method:'POST',body:JSON.stringify({character_id:Number(characterID)})});
   if(typeof result.url!=='string'||!result.url)throw new Error('The server returned no player link.');
   const url=new URL(result.url,window.location.origin);
   if(!['http:','https:'].includes(url.protocol)||!['/player','/player/'].includes(url.pathname))throw new Error('The server returned an invalid player link.');
   playerURL=url.href;input.value=playerURL;panel.hidden=false;
   output.textContent='Valid for '+number(result.valid_days||30)+' days. This link gives access to this account’s Adventures; share it only with the player.';
   if(popup&&!popup.closed)popup.location.replace(playerURL);
   else{output.textContent+=' The popup was blocked; copy the link to open or embed it.';input.focus();input.select();}
  }catch(error){if(popup&&!popup.closed)popup.close();$('#editor-error').textContent=error.message;}
  finally{button.disabled=false;button.textContent='Open Adventures';}
 };
 copy.onclick=async()=>{
  if(!playerURL)return;
  try{await navigator.clipboard.writeText(playerURL);output.textContent='Player link copied.';}
  catch(_){input.focus();input.select();output.textContent='Select and copy the player link above.';}
 };
}

