async function openSetting(name){try{const row=await api('/settings/'+encodeURIComponent(name)),value=row.value;const complex=value!==null&&typeof value==='object';const bool=typeof value==='boolean';const numeric=typeof value==='number';$('#editor-title').textContent=name;$('#editor-error').textContent='';$('#editor-form button[type=submit]').hidden=false;$('#editor-form button[type=submit]').disabled=false;$('#cancel-editor').textContent='Cancel';$('#editor-fields').innerHTML=`<p class="muted">${escapeHTML(applyPolicy(row.apply_mode))}. ${escapeHTML(row.apply_reason||'Saving persists the setting. Use Service controls if a restart is required.')}</p>${row.validation?`<p class="field-note">${escapeHTML(row.validation)}</p>`:''}${row.edit_mode==='new_version'?field('new_version','New version',Number(value?.version||row.version||0)+1,{type:'number',min:Number(value?.version||row.version||0)+1,note:'Publishes a new immutable configuration version.'}):''}${row.edit_mode==='select_version'?field('selected_version','Published version',value?.version,{choices:(row.versions||[]).map(v=>[v.version,`${v.name} · version ${v.version}`])}):''}${detailsGrid([['Category',row.category],['Type',row.value_type||typeof value],['Revision',row.revision],['Size',`${number(row.bytes)} bytes`]])}`+(complex?`<label>JSON value<textarea id="setting-json" class="json-editor" spellcheck="false"></textarea></label><div class="inline-actions"><button type="button" id="format-setting">Format JSON</button><span class="muted">Objects and arrays must contain valid JSON.</span></div>`:bool?field('setting_value','Value',value,{type:'checkbox'}):field('setting_value','Value',value===null?'null':value,{type:numeric?'number':'textarea',wide:true}));if(row.edit_mode==='select_version')$('#field-selected_version').onchange=e=>{const selected=(row.versions||[]).find(v=>String(v.version)===e.target.value);if(selected&&$('#setting-json'))$('#setting-json').value=JSON.stringify({version:selected.version,key:selected.name},null,2);};if(complex){$('#setting-json').value=JSON.stringify(value,null,2);$('#format-setting').onclick=()=>{try{$('#setting-json').value=JSON.stringify(JSON.parse($('#setting-json').value),null,2);$('#editor-error').textContent='';}catch(error){$('#editor-error').textContent='Invalid JSON: '+error.message;}};}if(numeric)$('#field-setting_value').step='any';saveEditor=async form=>{let next;if(complex){try{next=JSON.parse($('#setting-json').value);}catch(error){throw Error('Invalid JSON: '+error.message);}if(next===null||typeof next!=='object'||Array.isArray(next)!==Array.isArray(value))throw Error('Keep the original '+(Array.isArray(value)?'array':'object')+' value type.');}else if(bool)next=form.elements.setting_value.checked;else if(numeric){if(!form.elements.setting_value.value.trim())throw Error('Enter a number.');next=Number(form.elements.setting_value.value);if(!Number.isFinite(next))throw Error('Enter a finite number.');}else if(value===null){try{next=JSON.parse(form.elements.setting_value.value);}catch{throw Error('Enter a valid JSON value.');}}else next=form.elements.setting_value.value;const result=await api('/settings/'+encodeURIComponent(name),{method:'PATCH',body:JSON.stringify({value:next,expected_revision:row.revision,...(row.edit_mode==='new_version'?{new_version:Number(form.elements.new_version.value)}:{})})});$('#editor').close();await load();notice((result.changed_name?'Published '+result.changed_name+'. ':'Setting saved. ')+applyPolicy(result.apply_mode||row.apply_mode)+'. '+(result.apply_reason||row.apply_reason||''));};$('#editor').showModal();}catch(error){notice(error.message,true);}}
const serviceOperations=new Map();
function renderServiceControls(data){let rows=data.items||data.services||[];if(!Array.isArray(rows))rows=Object.entries(rows).map(([name,r])=>({name,...r}));return rows.map(r=>{const service=r.name||r.service||r.id;if(!['world','ecology','shop','ai','profiler'].includes(service))return '';return `<div class="service-control"><div><strong>${escapeHTML(r.label||service)}</strong><br>${status(r.ok??r.running??r.available,'Available','Unavailable')} <small class="muted">${escapeHTML(r.status||'')}</small></div><div><button type="button" data-service="${escapeHTML(service)}" ${r.restartable===false?'disabled':''}>${serviceOperations.has(service)?'Check restart status':'Restart'}</button><span class="service-confirm" data-confirm="${escapeHTML(service)}" hidden> ${service==='world'?'Players will be disconnected. ':''}Restart this service? <button type="button" class="danger" data-confirm-service="${escapeHTML(service)}">Confirm restart</button><button type="button" class="quiet" data-cancel-service="${escapeHTML(service)}">Cancel</button></span></div></div>`;}).join('')||'<p class="muted">No service controls are available.</p>';}
function bindServiceControls(){document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{if(serviceOperations.has(b.dataset.service)){restartService(b.dataset.service,b);return;}document.querySelectorAll('[data-confirm]').forEach(r=>r.hidden=r.dataset.confirm!==b.dataset.service);});document.querySelectorAll('[data-cancel-service]').forEach(b=>b.onclick=()=>b.closest('[data-confirm]').hidden=true);document.querySelectorAll('[data-confirm-service]').forEach(b=>b.onclick=()=>{const service=b.dataset.confirmService;b.closest('[data-confirm]').hidden=true;restartService(service,document.querySelector(`[data-service="${service}"]`));});}
async function restartService(service,button){const output=$('#service-operation-status');let operation=serviceOperations.get(service);if(!operation){operation={request_id:crypto.randomUUID()};serviceOperations.set(service,operation);}button.disabled=true;output.hidden=false;output.textContent='Submitting service restart…';let terminal=false;try{let receipt=operation.handle?await api('/operations/'+encodeURIComponent(operation.handle)):await api('/operations/restart',{method:'POST',body:JSON.stringify({service,request_id:operation.request_id})});operation.handle=receipt.handle||receipt.id||operation.handle;for(let tries=0;tries<60;tries++){if(receipt.status==='completed'){terminal=true;serviceOperations.delete(service);output.textContent=service+' restart completed. '+(receipt.result?.message||'');return;}if(['failed','cancelled'].includes(receipt.status)){terminal=true;serviceOperations.delete(service);throw Error(receipt.error||'Restart failed.');}output.textContent=service+' restart '+(receipt.status||'pending')+(receipt.phase?' ('+receipt.phase.replaceAll('_',' ')+')':'')+'. Waiting for confirmation…';if(!operation.handle)throw Error('Missing operation receipt.');await new Promise(resolve=>setTimeout(resolve,1000));receipt=await api('/operations/'+encodeURIComponent(operation.handle));}output.textContent='Restart still pending. Receipt: '+operation.handle+'. Check restart status to continue.';}catch(error){output.textContent=error.message+(terminal?'':operation.handle?' Check restart status to resume.':' Retry will reuse the same request identifier.');}finally{button.disabled=false;button.textContent=terminal?'Restart':operation.handle?'Check restart status':'Retry same restart';}}

